@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorRole {
  + position : int
}

class ReviewerRole {}

Person "1" -- "1" ResearchInstitution : worksFor
Person "1" -- "0..*" AuthorRole
AuthorRole "1" -- "1" ScientificArticle
Person "1" -- "0..*" ReviewerRole
ReviewerRole "1" -- "1" PeerReviewedPaper

ScientificArticle --|> PeerReviewedPaper
ScientificArticle --|> TechnicalReport

PeerReviewedPaper "1" -- "1..*" ReviewerRole
TechnicalReport "1" -- "1" ResearchInstitution
PeerReviewedPaper "1" -- "1" Journal

Publisher "1" -- "1..*" Journal
ResearchInstitution "1" -- "0..*" Journal : subscribesTo

@enduml

